pub fn cycle_selection(&mut self, window: &mut Window, cx: &mut Context<Self>) {
    let count = self.delegate.match_count();
    let index = self.delegate.selected_index();
    let new_index = if index + 1 == count { 0 } else { index + 1 };
    self.set_selected_index(new_index, Some(Direction::Down), true, window, cx);
    cx.notify();
}

pub fn cancel(&mut self, _: &menu::Cancel, window: &mut Window, cx: &mut Context<Self>) {
    if self.delegate.should_dismiss() {
        self.select_instead_of_open = false;
        self.delegate.clear_selection(cx);
        self.delegate.dismissed(window, cx);
        cx.emit(DismissEvent);
    }
}

fn toggle_multi_select(
    &mut self,
    _: &ToggleMultiSelect,
    _window: &mut Window,
    cx: &mut Context<Self>,
) {
    if !self.delegate.supports_multi_select() {
        cx.propagate();
        return;
    }
    self.select_instead_of_open = !self.select_instead_of_open;
    if !self.select_instead_of_open {
        self.delegate.clear_selection(cx);
    }
    cx.notify();
}

fn multi_select_next(
    &mut self,
    _: &MultiSelectNext,
    window: &mut Window,
    cx: &mut Context<Self>,
) {
    // Propagate so `tab` retains its other meanings (e.g.
    // `ConfirmCompletion`) in pickers without multi-select.
    if !self.delegate.supports_multi_select() {
        cx.propagate();
        return;
    }
    self.select_instead_of_open = true;
    let ix = self.delegate.selected_index();
    self.delegate.toggle_item_selected(ix, window, cx);
    self.select_next(&menu::SelectNext, window, cx);
    cx.notify();
}

fn confirm(&mut self, _: &menu::Confirm, window: &mut Window, cx: &mut Context<Self>) {
    if self.pending_update_matches.is_some()
        && !self.delegate.finalize_update_matches(
            self.query(cx),
            Duration::from_millis(16),
            window,
            cx,
        )
    {
        self.confirm_on_update = Some(false)
    } else {
        self.pending_update_matches.take();
        self.do_confirm(false, window, cx);
    }
}

fn secondary_confirm(
    &mut self,
    _: &menu::SecondaryConfirm,
    window: &mut Window,
    cx: &mut Context<Self>,
) {
    if self.pending_update_matches.is_some()
        && !self.delegate.finalize_update_matches(
            self.query(cx),
            Duration::from_millis(16),
            window,
            cx,
        )
    {
        self.confirm_on_update = Some(true)
    } else {
        self.do_confirm(true, window, cx);
    }
}

