6	    pub match_label: HighlightedMatch,
7	    pub paths: Vec<HighlightedMatch>,
8	    pub active: bool,
9	}
10	
11	#[derive(Debug, Clone, IntoElement)]
12	pub struct HighlightedMatch {
13	    pub text: String,
14	    pub highlight_positions: Vec<usize>,
15	    pub color: Color,
16	}
17	
18	impl HighlightedMatch {
19	    pub fn join(components: impl Iterator<Item = Self>, separator: &str) -> Self {
20	        // Track a running byte offset and insert separators between parts.
21	        let mut first = true;
22	        let mut byte_offset = 0;
23	        let mut text = String::new();
24	        let mut highlight_positions = Vec::new();
25	        for component in components {
26	            if !first {
27	                text.push_str(separator);
28	                byte_offset += separator.len();
29	            }
30	            first = false;
31	
32	            highlight_positions.extend(
33	                component
34	                    .highlight_positions
35	                    .iter()
36	                    .map(|position| position + byte_offset),
37	            );
38	            text.push_str(&component.text);
39	            byte_offset += component.text.len();
40	        }
41	
42	        Self {
43	            text,
44	            highlight_positions,
45	            color: Color::Default,
46	        }
47	    }
48	
49	    pub fn color(self, color: Color) -> Self {
50	        Self { color, ..self }
51	    }
52	}
53	impl RenderOnce for HighlightedMatch {
54	    fn render(self, _window: &mut Window, _: &mut App) -> impl IntoElement {
55	        HighlightedLabel::new(self.text, self.highlight_positions)
56	            .single_line()
57	            .color(self.color)
58	            .truncate()
59	    }
60	}
61	
62	impl HighlightedMatchWithPaths {
63	    pub fn render_paths_children(&mut self, element: Div) -> Div {
64	        element.children(self.paths.clone().into_iter().map(|path| {
65	            HighlightedLabel::new(path.text, path.highlight_positions)
66	                .single_line()
67	                .size(LabelSize::Small)
68	                .color(Color::Muted)
69	        }))
70	    }
71	
72	    pub fn is_active(mut self, active: bool) -> Self {
73	        self.active = active;
74	        self
75	    }
76	}
77	
78	impl RenderOnce for HighlightedMatchWithPaths {
79	    fn render(mut self, _window: &mut Window, _: &mut App) -> impl IntoElement {
80	        v_flex()
81	            .min_w_0()
82	            .child(
83	                h_flex()
84	                    .gap_1()
85	                    .child(self.match_label.clone())
86	                    .when_some(self.prefix.as_ref(), |this, prefix| {
87	                        this.child(Label::new(format!("({})", prefix)).color(Color::Muted))
88	                    })
89	                    .when(self.active, |this| {
