103	#[cfg(test)]
104	mod tests {
105	    use super::*;
106	
107	    #[test]
108	    fn join_offsets_positions_by_bytes_not_chars() {
109	        // "αβγ" is 3 Unicode scalar values, 6 bytes in UTF-8.
110	        let left_text = "αβγ".to_string();
111	        let right_text = "label".to_string();
112	        let left = HighlightedMatch {
113	            text: left_text,
114	            highlight_positions: vec![],
115	            color: Color::Default,
116	        };
117	        let right = HighlightedMatch {
