126	                .highlight_positions
127	                .iter()
128	                .all(|&p| joined.text.is_char_boundary(p)),
129	            "join produced non-boundary positions {:?} for text {:?}",
130	            joined.highlight_positions,
131	            joined.text
132	        );
133	    }
